// Revisa la plataforma y devuelve UN evento cuando algo cambia (falla nueva, falla que persiste o recuperacion).
// Si todo sigue igual no devuelve nada y el flujo termina ahi.
const DESTINATARIO = 'CAMBIAR_DESTINATARIO@ejemplo.com';   // editar aqui (o lo carga bootstrap_ia.py)
const REMITENTE = 'CAMBIAR_REMITENTE@ejemplo.com';
const REAVISO_MS = 15 * 60 * 1000;     // si una falla persiste, se vuelve a avisar cada 15 minutos
const estado = $getWorkflowStaticData('global');

const http = async (url, json = true) => {
  const t0 = Date.now();
  try {
    const r = await this.helpers.httpRequest({ url, method: 'GET', timeout: 5000, json, returnFullResponse: true, ignoreHttpStatusErrors: true });
    return { ok: r.statusCode >= 200 && r.statusCode < 300, codigo: r.statusCode, cuerpo: r.body, ms: Date.now() - t0 };
  } catch (e) {
    return { ok: false, codigo: 0, error: String(e.message || e).slice(0, 200), ms: Date.now() - t0 };
  }
};

const [p1, p2, e1, e2, e3, hap, api] = await Promise.all([
  http('http://patroni1:8008/cluster'), http('http://patroni2:8008/cluster'),
  http('http://etcd1:2379/health'), http('http://etcd2:2379/health'), http('http://etcd3:2379/health'),
  http('http://haproxy:7000/;csv', false),
  http('http://nginx-proxy/api/health'),
]);

// --- base de datos
const miembros = ((p1.ok && p1.cuerpo && p1.cuerpo.members) || (p2.ok && p2.cuerpo && p2.cuerpo.members) || []).map((m) => ({
  nombre: m.name, rol: m.role, estado: m.state, lineaTiempo: m.timeline, retrasoMB: m.lag,
}));
const lider = (miembros.find((m) => m.rol === 'leader') || {}).nombre || null;
const hayStandby = miembros.some((m) => /standby|replica/.test(m.rol || '') && /streaming|running/.test(m.estado || ''));
const nodosResponden = { patroni1: p1.ok, patroni2: p2.ok };
const etcdVivos = [e1, e2, e3].filter((x) => x.ok).length;

// --- HAProxy: ¿hay un servidor UP en el bloque "primary"?
let haproxyPrimario = null;
if (hap.ok && typeof hap.cuerpo === 'string') {
  const filas = hap.cuerpo.split('\n').filter((l) => /^primary,patroni\d,/.test(l));
  haproxyPrimario = filas.some((l) => l.split(',')[17] === 'UP');
}

// --- problemas activos
const problemas = [];   // { codigo, severidad, detalle }
for (const [nodo, vivo] of Object.entries(nodosResponden)) {
  if (!vivo) problemas.push({ codigo: 'NODO_DB_CAIDO', severidad: 'critica', detalle: `El nodo ${nodo} de la base de datos no responde (API de Patroni).` });
}
const nodosVivos = Object.values(nodosResponden).filter(Boolean).length;
if (nodosVivos === 0) problemas.push({ codigo: 'SIN_LIDER', severidad: 'critica', detalle: 'Ninguno de los dos nodos de base de datos responde.' });
else if (!lider) problemas.push({ codigo: 'SIN_LIDER', severidad: 'critica', detalle: 'El clúster de base de datos no tiene líder: las escrituras están detenidas.' });
if (nodosVivos === 1 && lider) problemas.push({ codigo: 'SIN_REPLICA', severidad: 'alta', detalle: 'Queda un solo nodo de base de datos: no hay réplica ni redundancia.' });
else if (nodosVivos === 2 && lider && !hayStandby) problemas.push({ codigo: 'SIN_REPLICA', severidad: 'media', detalle: 'La réplica no está en streaming todavía (se está sincronizando).' });
if (etcdVivos === 2) problemas.push({ codigo: 'ETCD_DEGRADADO', severidad: 'media', detalle: 'Falta uno de los tres etcd. El clúster sigue funcionando, pero sin margen de falla.' });
if (etcdVivos < 2) problemas.push({ codigo: 'ETCD_SIN_QUORUM', severidad: 'critica', detalle: `Solo ${etcdVivos} de 3 etcd responden: Patroni no puede elegir líder.` });
if (!hap.ok) problemas.push({ codigo: 'HAPROXY_CAIDO', severidad: 'critica', detalle: 'HAProxy no responde: la aplicación no puede llegar a la base.' });
else if (haproxyPrimario === false) problemas.push({ codigo: 'HAPROXY_SIN_PRIMARIO', severidad: 'critica', detalle: 'HAProxy no ve ningún nodo líder al que escribir.' });

// --- aplicacion
const apiCuerpo = (api.cuerpo && typeof api.cuerpo === 'object') ? api.cuerpo : {};
if (api.codigo === 503 || (api.ok && apiCuerpo.baseDeDatos && apiCuerpo.baseDeDatos !== 'conectada')) {
  problemas.push({ codigo: 'BACKEND_SIN_BASE_DE_DATOS', severidad: 'critica', detalle: `El backend responde pero no tiene base de datos${apiCuerpo.error ? ': ' + String(apiCuerpo.error).slice(0, 120) : '.'}` });
} else if (!api.ok) {
  problemas.push({ codigo: 'BACKEND_CAIDO', severidad: 'critica', detalle: `/api/health no responde correctamente (HTTP ${api.codigo || 'sin respuesta'}${api.error ? ', ' + api.error : ''}).` });
}

// --- cambio de lider (informativo)
const liderPrevio = estado.lider || null;
const cambioLider = !!(liderPrevio && lider && liderPrevio !== lider);
if (cambioLider) problemas.push({ codigo: 'LIDER_CAMBIO', severidad: 'alta', detalle: `El líder de la base de datos cambió de ${liderPrevio} a ${lider}.`, unico: true });
if (lider) estado.lider = lider;

// --- decidir si hay que avisar
const persistentes = problemas.filter((p) => !p.unico);
const firma = persistentes.map((p) => p.codigo + (p.codigo === 'NODO_DB_CAIDO' ? ':' + p.detalle : '')).sort().join('|');
const firmaPrevia = estado.firma || '';
const ahora = Date.now();
let tipo = null;
if (problemas.length && (firma !== firmaPrevia || cambioLider || ahora - (estado.ultimoAviso || 0) > REAVISO_MS)) tipo = 'falla';
else if (!problemas.length && firmaPrevia) tipo = 'recuperacion';
estado.firma = firma;
if (!tipo) return [];
estado.ultimoAviso = ahora;

const orden = { critica: 3, alta: 2, media: 1, baja: 0 };
const peor = problemas.slice().sort((a, b) => orden[b.severidad] - orden[a.severidad])[0];
const snapshot = {
  lider, miembros, etcdVivos: `${etcdVivos}/3`, haproxyPrimario: haproxyPrimario === null ? 'sin datos' : (haproxyPrimario ? 'UP' : 'DOWN'),
  api: { codigo: api.codigo, baseDeDatos: apiCuerpo.baseDeDatos || null, latenciaMs: api.ms },
};
const logs = [p1, p2, hap, api].filter((x) => x.error).map((x) => x.error);
if (apiCuerpo.error) logs.push(String(apiCuerpo.error).slice(0, 200));

const servicio = problemas.some((p) => /DB|LIDER|REPLICA|ETCD|HAPROXY/.test(p.codigo)) ? 'base-de-datos' : 'backend';
return [{ json: {
  origen: 'monitor-n8n', servicio, tipo,
  severidad: tipo === 'recuperacion' ? 'baja' : (peor ? peor.severidad : 'media'),
  evento: tipo === 'recuperacion' ? 'PLATAFORMA_RECUPERADA' : peor.codigo,
  eventos: problemas.map((p) => p.codigo),
  descripcion: tipo === 'recuperacion' ? 'Todos los componentes revisados volvieron a la normalidad.' : problemas.map((p) => p.detalle).join(' '),
  estado: snapshot, logs, hora: new Date().toISOString(),
  destinatario: DESTINATARIO, remitente: REMITENTE,
} }];

const AYUDA = {
  NODO_DB_CAIDO: { seccion: '01 · DB-01 / DB-02', pasos: ['docker ps -a --filter name=rayuela-patroni', 'docker logs --tail 50 rayuela-patroni1', 'docker start rayuela-patroni1   # el nodo caido', 'docker exec rayuela-patroni2 patronictl list'] },
  LIDER_CAMBIO: { seccion: '01 · DB-03', pasos: ['docker exec rayuela-patroni1 patronictl history', 'docker exec rayuela-patroni1 patronictl list'] },
  SIN_LIDER: { seccion: '01 · DB-04', pasos: ['docker exec rayuela-etcd1 etcdctl endpoint health --cluster', 'docker ps -a --filter name=rayuela-patroni --filter name=rayuela-etcd', 'docker logs --tail 80 rayuela-patroni1', 'docker logs --tail 80 rayuela-patroni2'] },
  SIN_REPLICA: { seccion: '01 · DB-02', pasos: ['docker start rayuela-patroni2   # el nodo caido', 'docker exec rayuela-patroni1 patronictl list'] },
  ETCD_DEGRADADO: { seccion: '01 · DB-05', pasos: ['docker exec rayuela-etcd1 etcdctl endpoint health --cluster', 'docker start rayuela-etcd2   # el etcd caido'] },
  ETCD_SIN_QUORUM: { seccion: '01 · DB-05', pasos: ['docker ps -a --filter name=rayuela-etcd', 'docker start rayuela-etcd1 rayuela-etcd2 rayuela-etcd3'] },
  HAPROXY_SIN_PRIMARIO: { seccion: '01 · DB-04', pasos: ['curl -s http://127.0.0.1:7000/', 'docker exec rayuela-patroni1 patronictl list'] },
  HAPROXY_CAIDO: { seccion: '00 · mapa de la plataforma', pasos: ['docker ps -a --filter name=rayuela-haproxy', 'docker logs --tail 40 rayuela-haproxy', 'docker compose --profile blue up -d haproxy'] },
  BACKEND_CAIDO: { seccion: '02 · APP-01 / APP-03', pasos: ['docker ps -a --filter name=rayuela-backend', 'docker logs --tail 100 rayuela-backend-blue', 'docker exec rayuela-nginx-proxy nginx -s reload'] },
  BACKEND_SIN_BASE_DE_DATOS: { seccion: '02 · APP-02', pasos: ['curl -s http://localhost/api/health', 'docker exec rayuela-patroni1 patronictl list'] },
};

// Se usa SOLO si el flujo de diagnostico no se pudo invocar (por ejemplo, esta inactivo): el aviso no se pierde.
const p = $('Revisar plataforma').first().json;
const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const ayuda = AYUDA[p.evento] || {};
const html = `<div style="font-family:Arial,sans-serif;max-width:680px">
<h2>[Rayuela] ${esc(p.tipo === 'recuperacion' ? 'RECUPERADO' : String(p.severidad).toUpperCase())} · ${esc(p.evento)}</h2>
<p>${esc(p.descripcion)}</p>
<p><strong>Hora:</strong> ${esc(p.hora)}</p>
<p><strong>Estado:</strong></p><pre style="background:#f4f4f5;padding:10px;white-space:pre-wrap">${esc(JSON.stringify(p.estado, null, 2))}</pre>
${ayuda.pasos ? `<p><strong>Primeros pasos (manual operativo, sección ${esc(ayuda.seccion)}):</strong></p><pre style="background:#f4f4f5;padding:10px;white-space:pre-wrap">${esc(ayuda.pasos.join('\n'))}</pre>` : ''}
<p style="color:#64748b;font-size:12px">Aviso directo del monitor: el flujo de diagnóstico con IA no estuvo disponible.</p></div>`;
return [{ json: { subject: `[Rayuela] ${p.tipo === 'recuperacion' ? 'RECUPERADO' : p.severidad.toUpperCase()} · ${p.evento} · ${p.servicio}`, html, destinatario: p.destinatario, remitente: p.remitente } }];
